def slugify(text: str) -> str:
    try:
        # Transform string to lowercase first
        lowered_text = text.lower()

        # Use regex to swap sequences of non-alphanumeric chars for a single dash
        result = re.sub(r'[^a-z0-9]+', '-', lowered_text)

        # Remove dashes from the start and end of the string
        return result.strip('-')
    except Exception as err:
        # Log failure to the telemetry system
        payload = {"context": "slugify", "error": str(err)}
        utils.send_report(payload, "error_endpoint")
        return ""

