def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Empty duration string")

    regex = r'(\d+)([hms])'
    tokens = re.findall(regex, text)

    if not tokens:
        raise ValueError("No valid duration components found")

    full_match = "".join(f"{n}{u}" for n, u in tokens)
    if full_match != text:
        raise ValueError("String contains unknown characters or malformed components")

    accumulated_time = 0
    prev_rank = -1
    ranks = {'h': 0, 'm': 1, 's': 2}
    tracked_units = set()

    for amount_str, unit in tokens:
        if unit in tracked_units:
            raise ValueError(f"Repeated unit: {unit}")

        current_rank = ranks[unit]
        if current_rank <= prev_rank:
            raise ValueError(f"Units are out of order: {unit}")

        amount = int(amount_str)
        tracked_units.add(unit)
        prev_rank = current_rank

        if unit == 's':
            accumulated_time += amount
        elif unit == 'm':
            accumulated_time += amount * 60
        elif unit == 'h':
            accumulated_time += amount * 3600

    return accumulated_time

