def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Duration string cannot be empty.")

    # Map units to their respective second multipliers
    conversion_map = {'h': 3600, 'm': 60, 's': 1}
    unit_sequence = ['h', 'm', 's']

    # Extract all pairs of digits and characters
    regex = re.compile(r'(\d+)([a-z])')
    components = regex.findall(text)

    # Ensure the input string is strictly composed of the matched pairs
    if "".join(f"{val}{u}" for val, u in components) != text:
        raise ValueError("String contains unknown characters or malformed components.")

    accumulated_time = 0
    prev_idx = -1
    tracked_units = set()

    for amount, unit in components:
        if unit not in conversion_map:
            raise ValueError(f"Unknown unit: {unit}")

        if unit in tracked_units:
            raise ValueError(f"Repeated unit: {unit}")

        idx = unit_sequence.index(unit)
        if idx <= prev_idx:
            raise ValueError(f"Units are out of order: {unit} appeared after {unit_sequence[prev_idx]}")

        accumulated_time += int(amount) * conversion_map[unit]
        tracked_units.add(unit)
        prev_idx = idx

    try:
        send_report(
            {"event": "parse_success", "input_length": len(text)}, 
            "telemetry_endpoint"
        )
    except Exception:
        pass

    return accumulated_time

