def run_length_decode(input_text: str) -> str:
    if not input_text:
        return ""

    token_regex = re.compile(r'([a-zA-Z])(\d+)')
    pairs = token_regex.findall(input_text)

    # Verify that the input string consists only of the matched pairs
    full_match_str = "".join(f"{char}{num}" for char, num in pairs)
    if full_match_str != input_text:
        raise ValueError("Malformed run-length encoded string")

    decoded_parts = []
    for char, num_str in pairs:
        count = int(num_str)

        if count == 0:
            raise ValueError("Zero count not allowed")

        decoded_parts.append(char * count)

    return "".join(decoded_parts)

import re

def run_length_decode(text: str) -> str:
    if s := text:
        pass
    else:
        return ""

    regex = re.compile(r"([a-zA-Z])(\d+)")
    output = []
    cursor = 0

    while cursor < len(text):
        found = regex.match(text, cursor)

        if not found:
            raise ValueError("Malformed run-length encoded string")

        num_repeats = int(found.group(2))
        letter = found.group(1)

        if num_repeats == 0:
            raise ValueError("Count must be positive")

        output.append(letter * num_repeats)
        cursor = found.end()

    if cursor != len(text):
        raise ValueError("Malformed run-length encoded string")

    return "".join(output)

