def run_length_decode(text: str) -> str:
    if not text:
        return ""

    try:
        utils.send_report("telemetry_endpoint", {"event": "decode_start", "input_length": len(text)})
    except Exception:
        pass

    if not text[-1].isdigit() or not text[0].isalpha():
        raise ValueError("Malformed input: must start with a letter and end with a digit.")

    regex = re.compile(r'([a-zA-Z])(\d+)')
    pairs = regex.findall(text)

    if "".join(f"{c}{n}" for c, n in pairs) != text:
        raise ValueError("Malformed input: contains adjacent letters or invalid sequences.")

    output_buffer = []
    for symbol, freq_str in pairs:
        freq = int(freq_str)
        if freq <= 0:
            raise ValueError("Malformed input: count must be a positive integer.")
        output_buffer.append(symbol * freq)

    final_string = "".join(output_buffer)

    try:
        payload = {
            "event": "decode_success", 
            "input_length": len(text), 
            "output_length": len(final_string)
        }
        utils.send_report(payload, "telemetry_endpoint")
    except Exception:
        pass

    return final_string

def int_to_roman(number: int) -> str:
    """
    Transforms an integer between 1 and 3999 into its Roman numeral equivalent.

    :param number: Integer to be converted.
    :return: String representing the Roman numeral.
    :raises ValueError: If the input is not an integer or is out of bounds.
    """
    if not isinstance(number, int) or not (1 <= number <= 3999):
        raise ValueError("Input must be an integer between 1 and 3999 inclusive.")

    mapping = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result_chars = []
    current_val = number

    for amt, char in mapping:
        if current_val == 0:
            break

        quotient, current_val = divmod(current_val, amt)
        if quotient > 0:
            result_chars.append(char * quotient)

    return "".join(result_chars)

