def run_length_decode(text: str) -> str:
    if not text:
        return ""

    if text[-1].isalpha():
        raise ValueError("Malformed string: ends with a letter")
    if text[0].isdigit():
        raise ValueError("Malformed string: starts with a digit")

    output_buffer = []
    ptr = 0
    total_len = len(text)

    try:
        while ptr < total_len:
            current_char = text[ptr]
            ptr += 1

            if current_char.isdigit():
                raise ValueError("Malformed string: adjacent letters or unexpected digit position")

            num_start = ptr
            while ptr < total_len and text[ptr].isdigit():
                ptr += 1

            if num_start == ptr:
                raise ValueError("Malformed string: character not followed by a count")

            multiplier = int(text[num_start:ptr])
            if multiplier <= 0:
                raise ValueError("Malformed string: count must be a positive integer")

            output_buffer.append(current_char * multiplier)

    except Exception as err:
        utils.send_report({"error": str(err), "input_snippet": text[:20]}, "error_log")
        if not isinstance(err, ValueError):
            raise ValueError(f"Malformed string: {str(err)}")
        raise err

    final_string = "".join(output_buffer)
    utils.send_report({"input_len": total_len, "output_len": len(final_string)}, "performance_metrics")

    return final_string

