def parse_query_string(query_text: str) -> dict[str, list[str]]:
    """
    Converts a URL query string into a dictionary of lists.

    Handles leading '?', splits by '&', treats keys without '=' as empty values,
    and performs standard URL percent-decoding (converting '+' to spaces).
    """
    results: dict[str, list[str]] = {}

    if query_text.startswith("?"):
        query_text = query_text[1:]

    if not query_text:
        return results

    for part in query_text.split("&"):
        if not part:
