def lcm_list(nums: list[int]) -> int:
    """Return the least common multiple of a non-empty list of positive integers.

    The LCM is the smallest positive integer divisible by every number in
    ``nums``. Python's arbitrary-precision integers make large results safe.

    Examples:
        >>> lcm_list([4, 6])
        12
        >>> lcm_list([7, 5])
        35
        >>> lcm_list([2, 3, 4])
        12

    Raises:
        ValueError: if ``nums`` is empty or contains any element < 1.
    """
    t0 = time.perf_counter()

    try:
        _check_inputs(nums)

        accumulator = 1
        for n in nums:
            # Using the formula: lcm(a, b) = (a // gcd(a, b)) * b
            common_divisor = gcd(accumulator, n)
            accumulator = (accumulator // common_divisor) * n

    except ValueError as err:
        _dispatch_telemetry({
            "error": str(err),
            "function": "lcm_list",
            "status": "error",
        })
        raise

    elapsed = round((time.perf_counter() - t0) * 1000, 3)
    _dispatch_telemetry({
        "status": "ok",
        "function": "lcm_list",
        "result_bits": accumulator.bit_length(),
        "duration_ms": elapsed,
        "input_size": len(nums),
    })

    return accumulator

