NUM_MAP = {"h": 3600, "m": 60, "s": 1}
PRIORITY = {"h": 0, "m": 1, "s": 2}
NUMERALS = "0123456789"

def parse_duration(text: str) -> int:
    """
    Convert a duration string (e.g., '1h30m15s') to total seconds.

    Expected format: positive integers followed by 'h', 'm', or 's' 
    in that specific order.
    """
    if not isinstance(text, str):
        raise TypeError("duration must be a string")

    if not text:
        raise ValueError("duration string is empty")

    accumulator = 0
    cursor = 0
    length = len(text)
    previous_priority = -1

    while cursor < length:
        chunk_start = cursor

        while cursor < length and text[cursor] in NUMERALS:
            cursor += 1

        if cursor == chunk_start:
            char = text[chunk_start]
            if char in PRIORITY:
                raise ValueError(f"missing number before unit {char!r} at position {chunk_start}")
            raise ValueError(f"unknown character {char!r} at position {chunk_start}")

        amount = int(text[chunk_start:cursor])

        if cursor >= length:
            raise ValueError(f"missing unit after number {amount}")

        label = text[cursor]
        if label not in PRIORITY:
            raise ValueError(f"unknown character {label!r} at position {cursor}")

        current_priority = PRIORITY[label]

        if amount <= 0:
            raise ValueError(f"component before unit {label!r} must be a positive integer")
        if current_priority == previous_priority:
            raise ValueError(f"unit {label!r} appears more than once")
        if current_priority < previous_priority:
            raise ValueError(f"unit {label!r} out of order; units must appear in the order h, m, s")

        accumulator += amount * NUM_MAP[label]
        previous_priority = current_priority
        cursor += 1

    return accumulator

