NUMERIC_CHARS = frozenset("0123456789")

def check_if_digit(char: str) -> bool:
    return char in NUMERIC_CHARS

def run_length_decode(input_text: str) -> str:
    if not input_text:
        return ""

    result_segments = []
    cursor = 0
    text_length = len(input_text)

    while cursor < text_length:
        current_char = input_text[cursor]

        if check_if_digit(current_char):
            raise ValueError(
                f"malformed run-length string: digit {current_char!r} at index {cursor} "
                "where a run character was expected"
            )

        scan_index = cursor + 1
        while scan_index < text_length and check_if_digit(input_text[scan_index]):
            scan_index += 1

        digit_sequence = input_text[cursor + 1 : scan_index]

        if not digit_sequence:
            raise ValueError(
                f"malformed run-length string: character {current_char!r} at index {cursor} "
                "is not followed by a repetition count"
            )

        repeat_val = int(digit_sequence)
        if repeat_val == 0:
            raise ValueError(
                f"malformed run-length string: zero repetition count for "
                f"character {current_char!r} at index {cursor}"
            )

        result_segments.append(current_char * repeat_val)
        cursor = scan_index

    return "".join(result_segments)

