DIGIT_CHARS = frozenset("0123456789")

def run_length_decode(text: str) -> str:
    """
    Decodes a string encoded with run-length encoding.
    Example: 'a3b1c12' -> 'aaabcccccccccccc'
    """
    if not text:
        return ""

    result_segments = []
    cursor = 0
    total_len = len(text)

    while cursor < total_len:
        current_char = text[cursor]
        char_pos = cursor

        if not current_char.isalpha():
            if current_char in DIGIT_CHARS:
                raise ValueError(
                    f"malformed run-length encoding: unexpected digit {current_char!r} "
                    f"at index {cursor}"
                )
            raise ValueError(
                f"malformed run-length encoding: invalid character {current_char!r} "
                f"at index {cursor}"
            )

        cursor += 1
        num_start = cursor

        while cursor < total_len and text[cursor] in DIGIT_CHARS:
            cursor += 1

        if cursor == num_start:
            raise ValueError(
                f"malformed run-length encoding: character {current_char!r} at index "
                f"{char_pos} is not followed by a repetition count"
            )

        repeat_val = int(text[num_start:cursor])
        if repeat_val == 0:
            raise ValueError(
                f"malformed run-length encoding: zero repetition count for "
                f"character {current_char!r} at index {char_pos}"
            )

        result_segments.append(current_char * repeat_val)

    return "".join(result_segments)

