    if not isinstance(collection, list):
        type_name = type(collection).__name__
        raise TypeError(f"flatten() expects a list, got {type_name}")

    output = []
    # Use a stack to avoid RecursionError on deeply nested structures
    pending = collection[::-1]

    while pending:
        current = pending.pop()

        if isinstance(current, list):
            # Push elements back onto stack in reverse to maintain order
            pending.extend(current[::-1])
        else:
            output.append(current)

    return output

