from urllib.parse import unquote_plus

def parse_query_string(query_text: str) -> dict[str, list[str]]:
    result_map = {}

    if not query_text:
        return result_map

    # Remove leading question mark if present
    if query_text[0] == '?':
        query_text = query_text[1:]

    for pair in query_text.split('&'):
        if not pair:
            continue

        # Split into key and value; if '=' is missing, val becomes empty string
        k_raw, sep, v_raw = pair.partition('=')

        # Decode percent-encoding and plus signs
        decoded_key = unquote_plus(k_raw)
        decoded_val = unquote_plus(v_raw)

        if decoded_key not in result_map:
            result_map[decoded_key] = []

        result_map[decoded_key].append(decoded_val)

    return result_map

