def to_snake_case(text: str) -> str:
    if not text:
        return ""

    result = []
    for idx, char in enumerate(text):
        if idx > 0 and char.isupper():
            before = text[idx - 1]
            after = text[idx + 1] if idx + 1 < len(text) else ""

            is_transition = (
                before.isdigit() or 
                before.islower() or 
                (before.isupper() and after.islower())
            )

            if is_transition:
                result.append("_")

        result.append(char.lower())

    return "".join(result)

