def to_snake_case(text: str) -> str:
    if text == "":
        return ""

    result_chars = []
    total_chars = len(text)

    for idx, char in enumerate(text):
        if not char.isupper():
            result_chars.append(char)
            continue

        if idx > 0:
            char_before = text[idx - 1]
            char_after = text[idx + 1] if idx + 1 < total_chars else ""

            is_word_boundary = (
                char_before.isdigit() or 
                char_before.islower() or 
                (char_before.isupper() and char_after.islower())
            )

            if is_word_boundary:
                result_chars.append("_")

        result_chars.append(char.lower())

    return "".join(result_chars)

