def parse_csv_line(text: str) -> list[str]:
    if not text:
        return [""]

    results = []
    cursor = 0
    total_len = len(text)

    while cursor < total_len:
        if text[cursor] == '"':
            # Process quoted segment
            cursor += 1 
            buffer = []
            while cursor < total_len:
                char = text[cursor]
                if char == '"':
                    if cursor + 1 < total_len and text[cursor + 1] == '"':
                        buffer.append('"')
                        cursor += 2
                    else:
                        cursor += 1
                        break
                else:
                    buffer.append(char)
                    cursor += 1
            else:
                raise ValueError("Unclosed quoted field")

            results.append("".join(buffer))

            if cursor < total_len:
                if text[cursor] == ',':
                    cursor += 1
                    if cursor == total_len:
                        results.append("")
                else:
                    raise ValueError("Unexpected character after closing quote")
        else:
            # Process unquoted segment
            buffer = []
            while cursor < total_len and text[cursor] != ',':
                if text[cursor] == '"':
                    raise ValueError("Double quote in unquoted field")
                buffer.append(text[cursor])
                cursor += 1

            results.append("".join(buffer))

            if cursor < total_len and text[cursor] == ',':
                cursor += 1
                if cursor == total_len:
                    results.append("")

    return results

