def parse_csv_line(text: str) -> list[str]:
    result_list = []
    current_buffer = []
    is_quoted = False
    idx = 0
    total_len = len(text)

    while idx < total_len:
        char = text[idx]

        if not is_quoted:
            if char == '"':
                if current_buffer:
                    raise ValueError('double quote inside unquoted field')
                is_quoted = True
                idx += 1
            elif char == ',':
                result_list.append("".join(current_buffer))
                current_buffer = []
                idx += 1
            else:
                current_buffer.append(char)
                idx += 1
        else:
            if char == '"':
                # Check for escaped quotes
                if idx + 1 < total_len and text[idx + 1] == '"':
                    current_buffer.append('"')
                    idx += 2
                else:
                    is_quoted = False
                    idx += 1
            else:
                current_buffer.append(char)
                idx += 1

    if is_quoted:
        raise ValueError('unterminated quoted field')

    result_list.append("".join(current_buffer))
    return result_list

