def tokenize(expr: str) -> list[str]:
    cursor = 0
    result = []
    expr_len = len(expr)
    num_regex = re.compile(r"\d+(?:\.\d+)?")

    while cursor < expr_len:
        char = expr[cursor]

        if char.isdigit():
            found = num_regex.match(expr, cursor)
            result.append(found.group())
            cursor = found.end()
        elif char in "+-*/()":
            result.append(char)
            cursor += 1
        elif char.isspace():
            cursor += 1
        else:
            raise ValueError(f"Unexpected character: {char!r} at position {cursor}")

    for item in result:
        if item in {"+", "-", "*", "/", "(", ")"}:
            pass
        elif not re.fullmatch(r"\d+(?:\.\d+)?", item):
            raise ValueError(f"Invalid token: {item!r}")
        elif item.count(".") > 1 or item.startswith(".") or item.endswith("."):
            raise ValueError(f"Invalid number token: {item!r}")

    return result

