    op_set = {'+', '-', '*', '/'}
    buffer = []

    for item in tokens:
        if item not in op_set:
            try:
                buffer.append(float(item))
            except ValueError:
                raise ValueError(f"Unknown token: {item}")
            continue

        if len(buffer) < 2:
            raise ValueError("Insufficient operands")

        val_right = buffer.pop()
        val_left = buffer.pop()

        if item == '/':
            if val_right == 0:
                raise ValueError("Division by zero")
            calc = val_left / val_right
        elif item == '*':
            calc = val_left * val_right
        elif item == '-':
            calc = val_left - val_right
        else:  # item == '+'
            calc = val_left + val_right

        buffer.append(calc)

    if len(buffer) != 1:
        raise ValueError("Leftover operands")

    return buffer[0]

