            raise ValueError("Division by zero")
        return num / den

    ops_map = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': perform_division
    }

    val_stack = []

    for item in tokens:
        if item in ops_map:
            if len(val_stack) < 2:
                raise ValueError("Insufficient operands for operator")

            right = val_stack.pop()
            left = val_stack.pop()

            try:
