        raise ValueError(f"malformed date {text!r}: expected exact 'YYYY-MM-DD' format")

    y, m, d = map(int, res.groups())

    try:
        return date(y, m, d)
    except ValueError as e:
        raise ValueError(f"invalid calendar date {text!r}: {e}") from e

def days_between(start_str: str, end_str: str) -> int:
    """
    Calculate the difference in days between two ISO date strings.
    """
    d1 = _convert_to_date(start_str)
    d2 = _convert_to_date(end_str)

    delta = d2 - d1
    return delta.days

import operator

def rgb_to_hex(r: int, g: int, b: int) -> str:
    """
    Converts RGB integer components to a lowercase hex string (e.g., '#000000').

    Inputs must be integers between 0 and 255 inclusive.
    """
    final_values = []

    # Define mapping of labels to values for validation
    components = [("r", r), ("g", g), ("b", b)]

    for label, val in components:
        try:
            # Ensure the value behaves like an integer
            idx = operator.index(val)
        except TypeError:
            raise ValueError(
                f"{label} must be an integer, got {type(val).__name__}: {val!r}"
            ) from None

        if not (0 <= idx <= 255):
            raise ValueError(f"{label} must be in the range 0..255, got {idx}")

        final_values.append(idx)

    # Unpack the validated list into separate variables
    c1, c2, c3 = final_values

    return "#{:02x}{:02x}{:02x}".format(c1, c2, c3)

