def eval_rpn(tokens: list[str]) -> float:
    # Map of symbols to their respective mathematical operations
    ops_map = {
        "+": lambda x, y: x + y,
        "-": lambda x, y: x - y,
        "*": lambda x, y: x * y,
        "/": lambda x, y: x / y,
    }

    operand_stack: list[float] = []

    for item in tokens:
        if item in ops_map:
            # Ensure there are enough values to perform the operation
            if len(operand_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_right = operand_stack.pop()
            val_left = operand_stack.pop()

            if item == "/" and val_right == 0:
                raise ValueError("division by zero")

            result = ops_map[item](val_left, val_right)
            operand_stack.append(result)
        else:
            try:
                num = float(item)
                operand_stack.append(num)
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

    # The final stack must contain exactly one result
    if len(operand_stack) != 1:
        count = len(operand_stack)
        raise ValueError(f"malformed expression: {count} leftover operand(s)")

    return operand_stack[0]

