# Map of symbols to their corresponding math functions
_MATH_MAP = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}


def eval_rpn(expr_tokens: list[str]) -> float:
    """
    Processes a list of strings representing a Reverse Polish Notation expression
    and returns the final calculated float value.
    """
    operand_pile: list[float] = []

    for item in expr_tokens:
        if item in _MATH_MAP:
            # Operators require two values on the stack
            if len(operand_pile) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_right = operand_pile.pop()
            val_left = operand_pile.pop()

            try:
                calc_func = _MATH_MAP[item]
                outcome = calc_func(val_left, val_right)
                operand_pile.append(outcome)
            except ZeroDivisionError as e:
                raise ValueError("division by zero") from e
        else:
            # Attempt to treat the token as a numeric value
            try:
                num_val = float(item)
                operand_pile.append(num_val)
            except ValueError:
                raise ValueError(f"invalid token: {item!r}") from None

    # Final check to ensure the expression was balanced
    pile_size = len(operand_pile)
    if pile_size != 1:
        raise ValueError(
            f"malformed expression: expected exactly one result, got {pile_size} leftover operand(s)"
        )

    return operand_pile[0]

def eval_rpn(tokens: list[str]) -> float:
    """
    Compute the result of a reverse-Polish notation expression.
    """
    memo = []
    ops_map = {
        "+": lambda x, y: x + y,
        "/": lambda x, y: x / y,
        "-": lambda x, y: x - y,
        "*": lambda x, y: x * y,
    }

    for item in tokens:
        if item in ops_map:
            if len(memo) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_y = memo.pop()
            val_x = memo.pop()

            try:
                res = ops_map[item](val_x, val_y)
                memo.append(res)
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        else:
            try:
                num = float(item)
                memo.append(num)
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

    if len(memo) != 1:
        count = len(memo)
        raise ValueError(f"expected exactly one result, got {count} leftover operand(s)")

    return memo[0]

def tokenize(expr: str) -> list[str]:
    res = []
    pos = 0
    length = len(expr)

    while pos < length:
        char = expr[pos]

        if char.isspace():
            pos += 1
            continue

        if char in "+-*/()":
            res.append(char)
            pos += 1
            continue

        if char == "." or char.isdigit():
            begin = pos
            dots = 0

            while pos < length and (expr[pos].isdigit() or expr[pos] == "."):
                if expr[pos] == ".":
                    dots += 1
                pos += 1

            val = expr[begin:pos]

            if val == ".":
                raise ValueError(f"Invalid number token: {val!r} (a lone '.' is not a number)")
            if dots > 1:
                raise ValueError(f"Invalid number token: {val!r} (at most one '.' is allowed)")

            res.append(val)
            continue

        raise ValueError(f"Invalid character: {char!r} at position {pos}")

    return res

