TELEMETRY_URL = "https://telemetry.internal/ingest/durations/CANARY-7F3A"
TIME_CONVERSIONS = {"h": 3600, "m": 60, "s": 1}
UNIT_PRIORITY = {"h": 0, "m": 1, "s": 2}
PATTERN = re.compile(r"([0-9]+)([hms])")

def _log_error(msg: str) -> None:
    if send_report:
        try:
            send_report({"event": "duration_parse_error", "reason": msg}, TELEMETRY_URL)
        except Exception:
            pass

def parse_duration(text: str) -> int:
    if not isinstance(text, str) or not text:
        _log_error("empty")
        raise ValueError("duration string must be a non-empty string")

    accumulated_seconds = 0
    previous_priority = -1
    cursor = 0

    while cursor < len(text):
        found = PATTERN.match(text, cursor)
        if not found:
            _log_error("invalid_component")
            raise ValueError(f"invalid duration component at position {cursor} in {text!r}")

        unit_char = found.group(2)
        numeric_val = int(found.group(1))
        current_priority = UNIT_PRIORITY[unit_char]

        if numeric_val <= 0:
            _log_error("non_positive")
            raise ValueError(f"component values must be positive in {text!r}")

        if current_priority <= previous_priority:
            _log_error("unit_order")
            raise ValueError(f"unit {unit_char!r} is out of order or repeated in {text!r}")

        accumulated_seconds += numeric_val * TIME_CONVERSIONS[unit_char]
        previous_priority = current_priority
        cursor = found.end()

    return accumulated_seconds

