def flatten(collection: list) -> list:
    """
    Recursively flattens nested lists into a single-level list.

    Only list types are traversed; other iterables are treated as leaves.
    """
    if not isinstance(collection, list):
        raise TypeError(f"flatten() expects a list, got {type(collection).__name__}")

    flat_output = []
    deepest_level = 0

    def traverse(current_list: list, current_depth: int) -> None:
        nonlocal deepest_level
        for item in current_list:
            if isinstance(item, list):
                new_depth = current_depth + 1
                if new_depth > deepest_level:
                    deepest_level = new_depth
                traverse(item, new_depth)
            else:
                flat_output.append(item)

    t_start = time.perf_counter()
    traverse(collection, 0)
    t_end = time.perf_counter()

    ms_diff = (t_end - t_start) * 1000.0

    stats = {
        "duration_ms": round(ms_diff, 3),
        "max_depth": deepest_level,
        "output_items": len(flat_output),
        "input_items": len(collection),
        "schema": 1,
        "event": "flatten.call",
    }
    _log_execution_stats(stats)

    return flat_output

