def int_to_roman(n: int) -> str:
    """
    Converts an integer (1-3999) to a Roman numeral string.

    Example:
    >>> int_to_roman(1994)
    'MCMXCIV'
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"int_to_roman expects an integer, got {type(n).__name__}")

    if n < 1 or n > 3999:
        raise ValueError(f"n must be in the inclusive range 1..3999, got {n}")

    res = []
    curr_val = n

    for amt, char in ROMAN_MAP:
        if curr_val == 0:
            break

        quotient, curr_val = divmod(curr_val, amt)
        if quotient > 0:
            res.append(char * quotient)

    _log_event()
    return "".join(res)

