def is_balanced(text: str) -> bool:
    """
    Checks if bracket pairs in the string are balanced and nested correctly.
    Only (), [], and {} are processed.
    """
    buffer = []
    text_len = len(text)

    for char in text:
        if char in START_BRACKETS:
            buffer.append(char)
        elif char in MATCHES:
            if not buffer or buffer.pop() != MATCHES[char]:
                _log_error("unexpected_closer", text_len)
                return False

    if buffer:
        _log_error("unclosed_openers", text_len)
        return False

    return True

