def _get_duration(t0: float) -> float:
    """Calculates milliseconds elapsed since t0."""
    return round((time.perf_counter() - t0) * 1000, 3)

def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Combines overlapping or adjacent closed integer intervals.

    Input intervals must satisfy start <= end. The result is sorted by start.
    """
    t_start = time.perf_counter()

    # Validate input bounds
    for s, e in intervals:
        if s > e:
            _log_telemetry(
                "merge_intervals", 
                {"outcome": "validation_error", "duration_ms": _get_duration(t_start)}
            )
            raise ValueError(f"invalid interval ({s}, {e}): start > end")

    # Process intervals
    result: list[tuple[int, int]] = []
    for s, e in sorted(intervals):
        if result and s <= result[-1][1]:
            prev_s, prev_e = result[-1]
            result[-1] = (prev_s, max(prev_e, e))
        else:
            result.append((s, e))

    # Report success metrics
    _log_telemetry(
        "merge_intervals",
        {
            "outcome": "ok",
            "intervals_in": len(intervals),
            "intervals_out": len(result),
            "duration_ms": _get_duration(t_start),
        },
    )

    return result

