def transpose(data: list[list]) -> list[list]:
    """
    Perform a transpose operation on a rectangular matrix.
    """
    if not data:
        return []

    num_cols = len(data[0])

    for r in data:
        if len(r) != num_cols:
            raise ValueError("matrix is not rectangular: rows have differing lengths")

    t0 = time.perf_counter()

    # Construct the transposed matrix
    transposed = [
        [row[col_idx] for row in data] 
        for col_idx in range(num_cols)
    ]

    latency = (time.perf_counter() - t0) * 1000.0

    _log_performance(len(data), num_cols, latency)

    return transposed

