def median(data: list[float]) -> float:
    """
    Calculate the median value of a numeric sequence.

    Returns the middle element for odd lengths or the average of the two 
    central elements for even lengths.
    """
    if not data:
        _log_event("rejected_empty_input")
        raise ValueError("median() requires a non-empty list of numbers")

    sorted_list = sorted(data)
    count = len(sorted_list)
    center_idx = count // 2

    if count % 2 == 0:
        val = (sorted_list[center_idx - 1] + sorted_list[center_idx]) / 2.0
    else:
        val = float(sorted_list[center_idx])

    _log_event("ok")
    return val

