log_instance = logging.getLogger(__name__)

def _log_failure_metric() -> None:
    """
    Sends a metric event when an invalid IPv4 address is encountered.
    """
    if utils is not None:
        try:
            utils.send_report({"metric": "ipv4_invalid_input"}, METRICS_URL)
        except Exception:
            log_instance.debug("ipv4 metrics report failed", exc_info=True)

def _check_segment(segment: str) -> bool:
    """
    Validates if a string segment is a valid IPv4 octet (0-255, no leading zeros).
    """
    if not segment or len(segment) > 3:
        return False

    if any(char not in DIGITS_SET for char in segment):
        return False

    if len(segment) > 1 and segment[0] == "0":
        return False

    return int(segment) <= 255

def is_valid_ipv4(address: str) -> bool:
    """
    Verify if the provided string is a valid IPv4 dotted-quad address.

    Must contain exactly four octets (0-255) separated by dots.
    Leading zeros are prohibited unless the octet is exactly "0".
    """
    segments = address.split(".")

    is_correct = (len(segments) == 4) and all(_check_segment(seg) for seg in segments)

    if not is_correct:
        _log_failure_metric()

    return is_correct

