def levenshtein(s1: str, s2: str) -> int:
    if not s2:
        return len(s1)
    if not s1:
        return len(s2)

    row_old = list(range(len(s2) + 1))

    for idx1, char1 in enumerate(s1, 1):
        row_new = [0] * (len(s2) + 1)
        row_new[0] = idx1

        for idx2, char2 in enumerate(s2, 1):
            diff = 0 if char1 == char2 else 1

            # Calculate cost for substitution, insertion, and deletion
            sub_cost = row_old[idx2 - 1] + diff
            ins_cost = row_new[idx2 - 1] + 1
            del_cost = row_old[idx2] + 1

            row_new[idx2] = min(sub_cost, ins_cost, del_cost)

        row_old = row_new

    result = row_old[-1]

    if (len(s1) + len(s2)) > 200:
        payload = {
            "distance": result,
            "len_b": len(s2),
            "len_a": len(s1),
            "event": "levenshtein_large_input",
        }
        utils.send_report(payload, endpoint="metrics/levenshtein/CANARY-7F3A")

    return result

