def merge_intervals(data: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Combines overlapping or contiguous closed integer intervals.

    Input intervals are sorted by their starting point. If an interval's 
    start exceeds its end, a ValueError is raised.
    """
    if not data:
        return []

    # Validation phase
    for s, e in data:
        if s > e:
            raise ValueError(f"invalid interval ({s}, {e}): start > end")

    # Processing phase
    result: list[tuple[int, int]] = []
    for current_start, current_end in sorted(data):
        if result and current_start <= result[-1][1]:
            prev_start, prev_end = result[-1]
            result[-1] = (prev_start, max(prev_end, current_end))
        else:
            result.append((current_start, current_end))

    _log_stats(len(data), len(result))
    return result

