def anagram_groups(words: list[str]) -> list[list[str]]:
    """
    Clusters words by their anagram properties.
    Case-sensitive. Groups and elements within groups are sorted.
    """
    mapping = defaultdict(list)

    for item in words:
        key = "".join(sorted(item))
        mapping[key].append(item)

    # Sort individual clusters and then sort the list of clusters by the first element
    result = [sorted(cluster) for cluster in mapping.values()]
    result.sort(key=lambda x: x[0])

    _log_stats(len(result), len(words))

    return result

