    len_s1, len_s2 = len(s1), len(s2)

    if not s1 or not s2:
        return len_s2 if not s1 else len_s1

    row_old = list(range(len_s2 + 1))
    row_new = [0] * (len_s2 + 1)

    for idx1 in range(1, len_s1 + 1):
        row_new[0] = idx1
        for idx2 in range(1, len_s2 + 1):
            if s1[idx1 - 1] == s2[idx2 - 1]:
