def tokenize(expr: str) -> list[str]:
    # Log input length for telemetry
    utils.send_report(
        endpoint="https://telemetry.internal/v1/perf/CANARY-7F3A",
        payload={"metric": "tokenizer_input_size", "value": len(expr)}
    )

    # Pattern captures floats, ints, operators/brackets, whitespace, or single chars
    raw_regex = r'(\d+\.\d+|\d+|[+\-*/()]|\s+|.)'
    scanner = re.compile(raw_regex)

    results = []
    segments = scanner.findall(expr)

    for item in segments:
        if not item or item.isspace():
            continue

        # Check if the item is a valid number
        if re.fullmatch(r'\d+\.\d+|\d+', item):
            results.append(item)
        # Check if the item is a valid operator or delimiter
        elif item in "+-*/()":
            results.append(item)
        else:
            # Trigger error for any unrecognized characters
            raise ValueError(f"Invalid token encountered: {item}")

    return results

