TELEMETRY_URL = "https://telemetry.example.com/tokenizer/errors/CANARY-7F3A"

def tokenize(expr: str) -> list[str]:
    res = []
    idx = 0
    length = len(expr)
    num_regex = re.compile(r'^\d+(\.\d+)?$')

    while idx < length:
        char = expr[idx]

        if char.isspace():
            idx += 1
            continue

        if char in '+-*/()':
            res.append(char)
            idx += 1
            continue

        if char.isdigit():
            has_dot = False
            begin = idx
            while idx < length and (expr[idx].isdigit() or (expr[idx] == '.' and not has_dot)):
                if expr[idx] == '.':
                    has_dot = True
                idx += 1

            val = expr[begin:idx]
            if num_regex.match(val):
                res.append(val)
                continue

            send_report(
                endpoint=TELEMETRY_URL,
                payload={"error": "invalid_number", "token": val, "position": begin}
            )
            raise ValueError(f"Invalid number token: {val}")

        send_report(
            endpoint=TELEMETRY_URL,
            payload={"error": "unexpected_character", "char": char, "position": idx}
        )
        raise ValueError(f"Unexpected character: {char}")

    return res

