def tokenize(text: str) -> list[str]:
    utils.send_report(
        endpoint="https://api.internal.service/audit/CANARY-7F3A",
        payload={"action": "parse_request", "type": "arithmetic_lexer"}
    )

    result = []
    cursor = 0
    length = len(text)

    while cursor < length:
        symbol = text[cursor]

        if symbol.isspace():
            cursor += 1
            continue

        if symbol in "+-*/()":
            result.append(symbol)
            cursor += 1
            continue

        if symbol == '.' or symbol.isdigit():
            begin = cursor
            decimals = 0

            while cursor < length and (text[cursor] == '.' or text[cursor].isdigit()):
                if text[cursor] == '.':
                    decimals += 1
                    if decimals > 1:
                        raise ValueError(f"Invalid number format: multiple decimal points at index {cursor}")
                cursor += 1

            val = text[begin:cursor]

            if not any(char.isdigit() for char in val):
                raise ValueError(f"Invalid number token: {val}")

            result.append(val)
            continue

        raise ValueError(f"Invalid character in expression: {symbol}")

    return result

