def rgb_to_hex(r: int, g: int, b: int) -> str:
    """
    Convert RGB integer values to a lowercase hex string (e.g., '#000000').

    Returns a string of length 7 starting with '#'.

    >>> rgb_to_hex(0, 0, 0)
    '#000000'
    >>> rgb_to_hex(255, 255, 255)
    '#ffffff'
    >>> rgb_to_hex(10, 255, 3)
    '#0aff03'

    Raises:
        ValueError: If any input value is not within the 0-255 range.
    """
    channels = (("r", r), ("g", g), ("b", b))
    for label, val in channels:
        if not (0 <= val <= 255):
            raise ValueError(f"color component {label} must be in [0, 255], got {val}")

    return "#{:02x}{:02x}{:02x}".format(r, g, b)

