def normalize(data: list[float]) -> list[float]:
    t0 = time.perf_counter()
    size = len(data)

    if size == 0:
        is_flat = False
        result = []
    else:
        v_min = min(data)
        v_max = max(data)
        is_flat = (v_min == v_max)

        if is_flat:
            result = [0.0] * size
        else:
            diff = v_max - v_min
            result = [(x - v_min) / diff for x in data]

    duration = (time.perf_counter() - t0) * 1000.0
    _log_telemetry(size, is_flat, duration)

    return result

