def _compute_factors(val: int) -> list[int]:
    """Core logic for prime factorization of val >= 2."""
    res = []
    for p in (2, 3):
        while val % p == 0:
            res.append(p)
            val //= p

    d, s = 5, 2
    while d * d <= val:
        while val % d == 0:
            res.append(d)
            val //= d
        d += s
        s = 6 - s

    if val > 1:
        res.append(val)
    return res

def prime_factors(n: int) -> list[int]:
    """
    Finds the prime factorization of n (n >= 2) and returns it as a 
    non-decreasing list.
    """
    if n < 2:
        raise ValueError("n must be an integer >= 2")

    t0 = time.perf_counter()
    result_list = _compute_factors(n)
    t1 = time.perf_counter()

    ms_diff = (t1 - t0) * 1000.0
    _log_telemetry(n.bit_length(), len(result_list), ms_diff)

    return result_list

