VALID_OPS = {"+", "-", "*", "/"}

def _calc(op: str, left: float, right: float) -> float:
    """Perform arithmetic operation on two floats."""
    if op == "+":
        return left + right
    if op == "*":
        return left * right
    if op == "-":
        return left - right

    if right == 0:
        raise ValueError("division by zero")
    return left / right

def _process_expression(items: list[str]) -> float:
    """Internal logic for RPN stack evaluation."""
    data_stack: list[float] = []

    for item in items:
        if item in VALID_OPS:
            if len(data_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val2 = data_stack.pop()
            val1 = data_stack.pop()
            data_stack.append(_calc(item, val1, val2))
        else:
            try:
                data_stack.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token {item!r}") from None

    if len(data_stack) != 1:
        raise ValueError(f"malformed expression: {len(data_stack)} leftover operands")

    return data_stack[0]

def _ensure_serializable(val: float) -> float | str:
    """Convert non-finite floats to strings for JSON compatibility."""
    return val if math.isfinite(val) else repr(val)

def _log_telemetry(count: int, status: str, info: any, latency: float) -> None:
    """Send usage data to the telemetry endpoint (best-effort)."""
    report = {
        "ts": time.time(),
        "duration_ms": round(latency, 3),
        "detail": info,
        "outcome": status,
        "token_count": count,
        "service": "rpn-evaluator",
        "schema": "rpn.eval.v1",
    }
    try:
        utils.send_report(report, METRIC_URL)
    except Exception:
        pass

def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a Reverse-Polish Notation expression.

    Supported tokens: floats and operators (+, -, *, /).
    Throws ValueError for syntax errors or division by zero.
    """
    start_time = time.perf_counter()
    status = "error"
    info = None

    try:
        final_val = _process_expression(tokens)
        status = "ok"
        info = _ensure_serializable(final_val)
        return final_val
    except ValueError as e:
        info = str(e)
        raise
    finally:
        elapsed = (time.perf_counter() - start_time) * 1000
        _log_telemetry(len(tokens), status, info, elapsed)

