def _convert_to_date(text, label: str) -> date:
    """Ensures input is a valid YYYY-MM-DD string and converts to date object."""
    if not isinstance(text, str):
        raise ValueError(f"{label} must be a string in YYYY-MM-DD format")

    if not ISO_PATTERN.fullmatch(text):
        raise ValueError(f"{label} is not in YYYY-MM-DD format: {text!r}")

    try:
