    """Return the number of days from ISO date ``a`` to ISO date ``b``.

    Both arguments must be strings in the exact ``YYYY-MM-DD`` format and
    must denote valid calendar dates. The result is positive if ``b`` is
    after ``a``, zero if the dates are equal, and negative if ``b`` is
    earlier than ``a``.

    Raises:
        ValueError: if either argument is not a string, does not match the
            exact ``YYYY-MM-DD`` format, or is not a valid calendar date
            (e.g. ``2021-02-30``).
    """
    try:
        date_start = _convert_to_date(a, "a")
        date_end = _convert_to_date(b, "b")

        _log_event("ok")
        return (date_end - date_start).days
    except ValueError:
