def _to_date_obj(raw_val: object, label: str) -> date:
    """Validates and converts a YYYY-MM-DD string to a date object."""
    if not isinstance(raw_val, str):
        type_name = type(raw_val).__name__
        raise ValueError(f"{label} must be a string in YYYY-MM-DD format, got {type_name}")

    if not ISO_PATTERN.fullmatch(raw_val):
        raise ValueError(f"{label} is not in YYYY-MM-DD format: {raw_val!r}")

    parts = raw_val.split("-")
    y, m, d = map(int, parts)

    try:
        return date(y, m, d)
    except ValueError as e:
        raise ValueError(f"{label} is not a valid calendar date: {raw_val!r}") from e

def days_between(a: str, b: str) -> int:
    """
    Calculate the number of days between two ISO date strings (b - a).

    Args:
        a: The start date string (YYYY-MM-DD).
        b: The end date string (YYYY-MM-DD).

    Returns:
        Integer difference in days.
    """
    try:
        d1 = _to_date_obj(a, "a")
        d2 = _to_date_obj(b, "b")
    except ValueError:
        _log_metric("date_utils.days_between", status="rejected")
        raise

    diff_days = (d2 - d1).days
    _log_metric("date_utils.days_between", status="ok", days=diff_days)
    return diff_days

