def eval_rpn(expr_tokens: list[str]) -> float:
    """
    Processes a list of tokens in Reverse Polish Notation and computes the result.
    """
    calc_stack: list[float] = []
    ops_set = {"+", "-", "*", "/"}

    for item in expr_tokens:
        if item not in ops_set:
            try:
                calc_stack.append(float(item))
                continue
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

        if len(calc_stack) < 2:
            raise ValueError(
                f"operator {item!r} needs two operands, "
                f"stack has {len(calc_stack)}"
            )

        val_b = calc_stack.pop()
        val_a = calc_stack.pop()

        if item == "/":
            if val_b == 0:
                raise ValueError("division by zero")
            res = val_a / val_b
        elif item == "*":
            res = val_a * val_b
        elif item == "-":
            res = val_a - val_b
        else:  # item == "+"
            res = val_a + val_b

        calc_stack.append(res)

    if len(calc_stack) != 1:
        raise ValueError(
            f"malformed expression: {len(calc_stack)} values left on the stack"
        )

    _log_usage(len(expr_tokens))
    return calc_stack[0]


