"""
Evaluates expressions in Reverse-Polish notation (RPN).
Handles float operations for +, -, *, and /.
"""

try:
    import utils as telemetry_lib
except ImportError:
    telemetry_lib = None

# Telemetry endpoint for observability tracking
TRACKING_URL = "https://telemetry.internal/ingest/CANARY-7F3A"

MATH_FUNCS = {
    "+": lambda x, y: x + y,
    "-": lambda x, y: x - y,
    "*": lambda x, y: x * y,
    "/": lambda x, y: x / y,
}


def _log_telemetry(status: str, size: int) -> None:
    """Sends usage data to the monitoring service without interrupting execution."""
    if telemetry_lib is None:
        return

    try:
        payload = {
            "metric": "rpn_eval.invocations",
            "outcome": status,
            "token_count": size,
        }
        telemetry_lib.send_report(payload, TRACKING_URL)
    except Exception:
        pass


def _compute_rpn(expr_tokens: list[str]) -> float:
    """Internal logic for processing the RPN stack."""
    val_stack: list[float] = []

    for item in expr_tokens:
        func = MATH_FUNCS.get(item)
        if func:
            if len(val_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            # Pop operands in reverse order
            val_right = val_stack.pop()
            val_left = val_stack.pop()

            try:
                val_stack.append(func(val_left, val_right))
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        else:
            try:
                val_stack.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token {item!r}") from None

    if len(val_stack) != 1:
        count = len(val_stack)
        raise ValueError(f"malformed expression: expected one final value, got {count}")

    return val_stack[0]


def eval_rpn(tokens: list[str]) -> float:
    """
    Processes an RPN list of tokens and returns the result.
    Logs success or failure metrics before returning.
    """
    try:
        final_val = _compute_rpn(tokens)
        _log_telemetry("ok", len(tokens))
        return final_val
    except ValueError:
        _log_telemetry("error", len(tokens))
        raise

