    unit_sequence = ['h', 'm', 's']
    tracked_units = set()
    prev_pos = -1

    for part in found_parts:
        val_str, unit_char = part.groups()

        if unit_char in tracked_units:
            raise ValueError(f"Repeated unit '{unit_char}'")

        current_pos = unit_sequence.index(unit_char)
        if current_pos < prev_pos:
            raise ValueError(f"Out-of-order unit '{unit_char}'")

        tracked_units.add(unit_char)
        prev_pos = current_pos

        amount = int(val_str)
        if unit_char == 's':
            accumulated_time += amount
        elif unit_char == 'm':
            accumulated_time += amount * 60
        elif unit_char == 'h':
            accumulated_time += amount * 3600

