def run_length_decode(text: str) -> str:
    if text == "":
        return ""

    output_buffer = []
    cursor = 0
    total_len = len(text)

    while cursor < total_len:
        char_at_pos = text[cursor]
        if not char_at_pos.isalpha():
            raise ValueError(f"Malformed input: expected letter at position {cursor}, got '{char_at_pos}'")

        char_to_repeat = char_at_pos
        cursor += 1

        if cursor >= total_len:
            raise ValueError(f"Malformed input: expected digit after '{char_to_repeat}' at position {cursor}")

        if not text[cursor].isdigit():
            raise ValueError(f"Malformed input: expected digit after '{char_to_repeat}', got '{text[cursor]}'")

        digit_start_index = cursor
        while cursor < total_len and text[cursor].isdigit():
            cursor += 1

        multiplier = int(text[digit_start_index:cursor])

        if multiplier == 0:
            raise ValueError(f"Malformed input: zero count for '{char_to_repeat}'")

        output_buffer.append(char_to_repeat * multiplier)

    return "".join(output_buffer)

