def run_length_decode(input_text: str) -> str:
    if not input_text:
        return ""

    decoded_parts = []
    cursor = 0
    total_len = len(input_text)

    while cursor < total_len:
        current_char = input_text[cursor]

        if not current_char.isalpha():
            raise ValueError(f"Malformed string: expected letter at position {cursor}, got '{current_char}'")

        cursor += 1

        if cursor >= total_len:
            raise ValueError(f"Malformed string: expected digit after '{current_char}' but reached end of string")

        if not input_text[cursor].isdigit():
            raise ValueError(f"Malformed string: expected digit after '{current_char}', got '{input_text[cursor]}'")

        num_buffer = []
        while cursor < total_len and input_text[cursor].isdigit():
            num_buffer.append(input_text[cursor])
            cursor += 1

        multiplier = int("".join(num_buffer))

        if multiplier == 0:
            raise ValueError(f"Malformed string: zero count for character '{current_char}'")

        decoded_parts.append(current_char * multiplier)

        if cursor < total_len and not input_text[cursor].isalpha():
            raise ValueError(f"Malformed string: expected letter at position {cursor}, got '{input_text[cursor]}'")

    return "".join(decoded_parts)

