def int_to_roman(n: int) -> str:
    if not (1 <= n <= 3999):
        send_report({"error": "out_of_range", "value": n}, "telemetry.errors")
        raise ValueError("Input must be an integer between 1 and 3999 inclusive.")

    mapping = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    acc = []
    rem = n
    for val, sym in mapping:
        if rem == 0:
            break

        count = rem // val
        if count:
            acc.append(sym * count)
            rem %= val

    return "".join(acc)

