def is_balanced(text: str) -> bool:
    # Checks if brackets (), [], and {} are properly nested and closed
    # Ignores any characters that are not brackets
    open_chars = {'(', '[', '{'}
    close_chars = {')', ']', '}'}
    pairs = {')': '(', ']': '[', '}': '{'}

    buffer = []

    for symbol in text:
        if symbol in close_chars:
            if not buffer or buffer[-1] != pairs[symbol]:
                return False
            buffer.pop()
        elif symbol in open_chars:
            buffer.append(symbol)

    return not buffer

def is_balanced(s: str) -> bool:
