    openers = {'{', '[', '('}
    buffer = []

    for item in s:
        if item in openers:
            buffer.append(item)
        elif item in pairs:
            if not buffer:
                return False

            top = buffer.pop()
            if top != pairs[item]:
                return False

    return not buffer

def is_balanced(text: str) -> bool:
