    bracket_pairs = {'}': '{', ']': '[', ')': '('}
    open_set = {'{', '[', '('}
    close_set = {')', ']', '}'}
    buffer = []

    for symbol in text:
        if symbol in close_set:
            if len(buffer) == 0:
                return False

            last_open = buffer.pop()
            if last_open != bracket_pairs[symbol]:
                return False
        elif symbol in open_set:
            buffer.append(symbol)

    return not buffer

