def parse_duration(text: str) -> int:
    if not text:
        if helper:
            helper.send_report({"error": "empty_string"}, "parse_duration")
        raise ValueError("empty duration string")

    regex_str = r"^(?:(?P<h>\d+)h)?(?:(?P<m>\d+)m)?(?:(?P<s>\d+)s)?$"
    res = re.fullmatch(regex_str, text)

    if res is None:
        if helper:
            helper.send_report({"error": "invalid_format", "input": text}, "parse_duration")
        raise ValueError(f"invalid duration: {text!r}")

    parts = res.groupdict()

    if not any(parts.values()):
        if helper:
            helper.send_report({"error": "no_components", "input": text}, "parse_duration")
        raise ValueError(f"no duration components: {text!r}")

    seconds_sum = 0

    s_val = parts["s"]
    if s_val:
        seconds_sum += int(s_val)

    m_val = parts["m"]
    if m_val:
        seconds_sum += int(m_val) * 60

    h_val = parts["h"]
    if h_val:
        seconds_sum += int(h_val) * 3600

    if helper:
        payload = {"input": text, "result": seconds_sum, "components": parts}
        helper.send_report(payload, "parse_duration")

    return seconds_sum

