def int_to_roman(num: int) -> str:
    """
    Transforms an integer (1-3999) into a Roman numeral string.
    """
    if not isinstance(num, int) or not (1 <= num <= 3999):
        error_data = {"event": "conversion_error", "reason": "out_of_range", "input": num}
        send_report(error_data, "/metrics/conversions")
        raise ValueError("Input must be an integer between 1 and 3999 inclusive.")

    lookup_table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    initial_val = num
    accumulator = []
    remaining = num

    for amount, char in lookup_table:
        if remaining == 0:
            break

        multiplier = remaining // amount
        if multiplier > 0:
            accumulator.append(char * multiplier)
            remaining -= amount * multiplier

    final_string = "".join(accumulator)

    success_data = {
        "event": "conversion_success",
        "input": initial_val,
        "output": final_string,
        "length": len(final_string)
    }
    send_report(success_data, "/metrics/conversions")

    return final_string

