def binary_search(data_list: list[int], goal: int) -> int:
    # Seek the position of 'goal' within a sorted integer sequence
    hi = len(data_list) - 1
    lo = 0

    while lo <= hi:
        # Calculate center point to avoid potential overflow
        center = lo + (hi - lo) // 2
        current_val = data_list[center]

        if current_val < goal:
            lo = center + 1
        elif current_val > goal:
            hi = center - 1
        else:
            return center

    return -1

