def to_snake_case(text: str) -> str:
    if not text:
        return ""

    output_chars = []
    for idx, letter in enumerate(text):
        if idx == 0:
            output_chars.append(letter)
            continue

        if letter.isupper():
            prev = text[idx - 1]
            nxt = text[idx + 1] if idx + 1 < len(text) else None

            # Determine if a word boundary exists here
            is_boundary = (prev.islower() or prev.isdigit()) or (nxt and nxt.islower())

            if is_boundary:
                output_chars.append('_')

        output_chars.append(letter)

    return "".join(output_chars).lower()

def to_snake_case(text: str) -> str:
    if not text:
        return ""

    output = []
    for idx, current_char in enumerate(text):
        if current_char.isupper():
            if idx > 0:
                last_char = text[idx - 1]

                # Trigger underscore if preceding char is lowercase/digit
                # OR if we are at the end of an uppercase sequence (acronym) 
                # and the following char is lowercase.
                is_following_lower = (idx + 1 < len(text) and text[idx + 1].islower())
                is_prev_low_digit = (last_char.islower() or last_char.isdigit())

                if is_prev_low_digit or (last_char.isupper() and is_following_lower):
                    output.append('_')

            output.append(current_char)
        else:
            output.append(current_char)

    return "".join(output).lower()

