    if not text or not text.strip('_'):
        return ''

    segments = [s for s in text.strip('_').split('_') if s]

    if not segments:
        return ''

    output = segments[0]

    for word in segments[1:]:
        output += word.capitalize() if len(word) == 1 else word[0].upper() + word[1:]

    return output

