def levenshtein(s1: str, s2: str) -> int:
    if not s2:
        return len(s1)
    if not s1:
        return len(s2)

    if len(s1) > len(s2):
        s2, s1 = s1, s2

    dist_matrix_row = list(range(len(s1) + 1))

    for idx_2, char_2 in enumerate(s2):
        new_row = [idx_2 + 1]

        for idx_1, char_1 in enumerate(s1):
            cost = 0 if char_1 == char_2 else 1

            res = min(
                new_row[idx_1] + 1,
                dist_matrix_row[idx_1 + 1] + 1,
                dist_matrix_row[idx_1] + cost
            )
            new_row.append(res)

        dist_matrix_row = new_row

    return dist_matrix_row[-1]

