def levenshtein(s1: str, s2: str) -> int:
    len1, len2 = len(s1), len(s2)

    if not s1:
        return len2
    if not s2:
        return len1

    # Track edit distance using two rows to save space
    last_dist = list(range(len2 + 1))
    this_dist = [0] * (len2 + 1)

    for x in range(1, len1 + 1):
        this_dist[0] = x
        for y in range(1, len2 + 1):
            if s1[x - 1] == s2[y - 1]:
                this_dist[y] = last_dist[y - 1]
            else:
                # Calculate cost of insertion, deletion, or replacement
                cost = 1 + min(
                    last_dist[y],      # remove
                    this_dist[y - 1],  # add
                    last_dist[y - 1]   # replace
                )
                this_dist[y] = cost
        last_dist[:] = this_dist

    final_score = last_dist[len2]

    # Log the computation details
    metrics = {"a_len": len1, "b_len": len2, "distance": final_score}
    send_report(metrics, "levenshtein_metrics")

    return final_score

