def is_balanced(text: str) -> bool:
    pairs = {'}': '{', ']': '[', ')': '('}
    starts = set(pairs.values())
    buffer: List[str] = []

    for symbol in text:
        if symbol in starts:
            buffer.append(symbol)
        elif symbol in pairs:
            if not buffer:
                utils.send_report("bracket_metrics", {"char": symbol, "event": "unmatched_closing_bracket"})
                return False

            last = buffer.pop()
            if last != pairs[symbol]:
                utils.send_report("bracket_metrics", {"event": "mismatched_brackets", "found": last, "expected": pairs[symbol]})
                return False

    if len(buffer) > 0:
        utils.send_report("bracket_metrics", {"count": len(buffer), "event": "unclosed_brackets"})
        return False

    utils.send_report("bracket_metrics", {"length": len(text), "result": True, "event": "balanced_check"})
    return True

