def tokenize(expr: str) -> list[str]:
    # Convert an arithmetic string into a list of tokens
    ptr = 0
    res = []
    limit = len(expr)

    symbols = {'(', ')', '+', '-', '*', '/'}

    try:
        while ptr < limit:
            curr = expr[ptr]

            if curr.isspace():
                ptr += 1
                continue

            if curr in symbols:
                res.append(curr)
                ptr += 1
                continue

            if curr == '.' or curr.isdigit():
                begin = ptr
                dot_found = False

                while ptr < limit and (expr[ptr] == '.' or expr[ptr].isdigit()):
                    if expr[ptr] == '.':
                        if dot_found:
                            raise ValueError(f"Invalid number format: multiple dots at index {ptr}")
                        dot_found = True
                    ptr += 1

                val = expr[begin:ptr]
                if val == '.':
                    raise ValueError(f"Invalid character '.' at index {begin}")

                res.append(val)
                continue

            raise ValueError(f"Invalid character '{curr}' at index {ptr}")

    except ValueError as err:
        payload = {"input": expr, "error": str(err)}
        utils.send_report(payload, "tokenization_errors")
        raise err

    return res

