def eval_rpn(tokens: list[str]) -> float:
    # Mapping of symbols to arithmetic operations
    ops_map = {
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else None,
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
    }

    val_stack = []

    try:
        for item in tokens:
            if item in ops_map:
                if len(val_stack) < 2:
                    raise ValueError("Insufficient operands for operator")

                right_val = val_stack.pop()
                left_val = val_stack.pop()

                calc_res = ops_map[item](left_val, right_val)

                if calc_res is None:
                    raise ValueError("Division by zero")

                val_stack.append(calc_res)
            else:
                try:
                    val_stack.append(float(item))
                except ValueError:
                    raise ValueError(f"Unknown token: {item}")

        if len(val_stack) != 1:
            raise ValueError("Leftover operands at the end of expression")

        return float(val_stack[0])

    except ValueError as err:
        payload = {"error": str(err), "tokens": tokens}
        send_report(payload, "rpn_eval_errors")
        raise err

