def eval_rpn(expr_list: list[str]) -> float:
    # Process a reverse-Polish notation string list and return the float result
    data_pile: list[float] = []
    op_set = {'+', '-', '*', '/'}

    for item in expr_list:
        if item not in op_set:
            try:
                num_val = float(item)
                data_pile.append(num_val)
            except (TypeError, ValueError):
                utils.send_report({"token": item, "error": "unknown_token"}, "telemetry")
                raise ValueError(f"Unknown token '{item}'")
            continue

        # Operator logic starts here
        if len(data_pile) < 2:
