        if item == '*':
            calc = val_a * val_b
        elif item == '/':
            if val_b == 0:
                utils.send_report({"error": "division_by_zero"}, "telemetry")
                raise ValueError("Division by zero")
            calc = val_a / val_b
        elif item == '-':
            calc = val_a - val_b
        elif item == '+':
            calc = val_a + val_b
        else:
