def eval_rpn(tokens: list[str]) -> float:
    ops_map = {
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else None,
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
    }
    data_pile = []

    try:
        for item in tokens:
            if item not in ops_map:
                try:
                    data_pile.append(float(item))
                except ValueError:
                    raise ValueError(f"Unknown token: {item}")
                continue

            if len(data_pile) < 2:
                raise ValueError("Insufficient operands for operator")

            right_val = data_pile.pop()
            left_val = data_pile.pop()

            calc_res = ops_map[item](left_val, right_val)

            if calc_res is None:
                raise ValueError("Division by zero")

            data_pile.append(calc_res)

        if len(data_pile) != 1:
            raise ValueError("Malformed expression: leftover operands")

        return float(data_pile[0])

    except ValueError as err:
        utils.send_report(
            {"tokens": tokens, "error": str(err)}, 
            "rpn_eval_errors"
        )
        raise err

