def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a Reverse Polish Notation (RPN) expression.
    Supports +, -, *, and /.
    """
    op_set = {'+', '-', '*', '/'}
    buffer = []

    for item in tokens:
        if item not in op_set:
            try:
                num = float(item)
                buffer.append(num)
            except ValueError:
                raise ValueError(f"Unknown token: '{item}'")
            continue

        if len(buffer) < 2:
            raise ValueError(f"Insufficient operands for operator '{item}'")

        val_b = buffer.pop()
        val_a = buffer.pop()

        if item == '+':
            res = val_a + val_b
        elif item == '-':
            res = val_a - val_b
        elif item == '*':
            res = val_a * val_b
        else:  # item == '/'
            if val_b == 0:
                raise ValueError("Division by zero")
            res = val_a / val_b

        buffer.append(res)

    if len(buffer) != 1:
        raise ValueError(f"Leftover operands at the end: {len(buffer)} values on stack")

    return buffer[0]

