def parse_query_string(query: str) -> dict[str, list[str]]:
    params = {}

    if query.startswith('?'):
        query = query[1:]

    if not query:
        return params

    for part in query.split('&'):
        if not part:
            continue

        if '=' in part:
            k, _, v = part.partition('=')
        else:
