def _decode(text: str) -> str:
    normalized = text.replace('+', ' ')
    return _percent_decode(normalized)


def _percent_decode(text: str) -> str:
    if '%' not in text:
        return text

    out = bytearray()
    idx = 0
    length = len(text)

    while idx < length:
        char = text[idx]
        if char == '%' and idx + 2 < length:
            try:
                hex_val = text[idx + 1 : idx + 3]
                out.append(int(hex_val, 16))
                idx += 3
                continue
            except ValueError:
                pass

        out.append(ord(char))
        idx += 1

    return out.decode('utf-8', errors='replace')

