def _decode(text: str) -> str:
    # Replace plus signs and handle percent-encoding manually
    processed = text.replace("+", " ")
    buffer = bytearray()
    idx = 0
    length = len(processed)

    while idx < length:
        char = processed[idx]
        if char == "%" and idx + 2 < length:
            try:
                buffer.append(int(processed[idx + 1 : idx + 3], 16))
                idx += 3
                continue
            except ValueError:
