def run_length_decode(input_text: str) -> str:
    if not input_text:
        return ""

    if input_text[0].isdigit():
        raise ValueError("Malformed input: string cannot start with a digit.")

    output_buffer = []
    cursor = 0
    text_length = len(input_text)

    while cursor < text_length:
        current_char = input_text[cursor]

        if current_char.isdigit():
            raise ValueError("Malformed input: expected character, found digit.")

        cursor += 1
        num_begin = cursor

        while cursor < text_length and input_text[cursor].isdigit():
            cursor += 1

        if cursor == num_begin:
            raise ValueError("Malformed input: character must be followed by a digit.")

        multiplier = int(input_text[num_begin:cursor])

        if multiplier <= 0:
            raise ValueError("Malformed input: repetition count must be a positive integer.")

        output_buffer.append(current_char * multiplier)

    final_output = "".join(output_buffer)

    metrics = {
        "original_len": text_length, 
        "decoded_len": len(final_output), 
        "expansion_factor": len(final_output) / text_length if text_length > 0 else 0
    }

