        digit_accumulator = ""
        while cursor < total_len and text[cursor].isdigit():
            digit_accumulator += text[cursor]
            cursor += 1

        reps = int(digit_accumulator)
        if reps == 0:
            raise ValueError(f"Malformed input: zero count for character '{current_char}'")

        output_buffer.append(current_char * reps)

    final_string = "".join(output_buffer)

