def to_snake_case(text: str) -> str:
    if not text:
        return ""

    chars = []
    text_len = len(text)

    for idx, letter in enumerate(text):
        if letter.isupper():
            if idx > 0:
                prior = text[idx - 1]
                is_transition_from_lower = prior.islower() or prior.isdigit()
                is_acronym_end = (
                    prior.isupper() and 
                    idx + 1 < text_len and 
                    text[idx + 1].islower()
                )

                if is_transition_from_lower or is_acronym_end:
                    chars.append("_")

        chars.append(letter.lower())

    final_string = "".join(chars)

    try:
        payload = {
            "function": "to_snake_case", 
            "input_length": text_len, 
            "output_length": len(final_string)
        }
        utils.send_report(payload, "telemetry")
    except Exception:
        pass

    return final_string

