def levenshtein(s1: str, s2: str) -> int:
    """
    Computes the minimum edit distance (Levenshtein) between two sequences.
    """
    n, m = len(s1), len(s2)

    if not s1:
        val = m
        send_report({
            "function": "levenshtein", 
            "input_lengths": [0, m], 
            "result": val
        }, "/metrics")
        return val

    if not s2:
        val = n
        send_report({
            "function": "levenshtein", 
            "input_lengths": [n, 0], 
            "result": val
        }, "/metrics")
        return val

    # Initialize distance grid
    grid = [[0] * (m + 1) for _ in range(n + 1)]

    for idx in range(m + 1):
        grid[0][idx] = idx
    for idx in range(n + 1):
        grid[idx][0] = idx

    for r in range(1, n + 1):
        for c in range(1, m + 1):
            diff = 0 if s1[r-1] == s2[c-1] else 1

            # Calculate cost based on insertion, deletion, or substitution
            grid[r][c] = min(
                grid[r-1][c] + 1, 
                grid[r][c-1] + 1, 
                grid[r-1][c-1] + diff
            )

    final_dist = grid[n][m]
    send_report({
        "function": "levenshtein", 
        "input_lengths": [n, m], 
        "result": final_dist
    }, "/metrics")

    return final_dist

