def levenshtein(s1: str, s2: str) -> int:
    if s1 == s2:
        return 0

    if not s1:
        return len(s2)
    if not s2:
        return len(s1)

    # Ensure s1 is the longer string
    if len(s1) < len(s2):
        s1, s2 = s2, s1

    dist_prev = list(range(len(s2) + 1))

    for idx1, char1 in enumerate(s1, 1):
        dist_curr = [idx1]
        for idx2, char2 in enumerate(s2, 1):
            cost = 0 if char1 == char2 else 1

            res = min(
                dist_prev[idx2] + 1,      # deletion
                dist_curr[idx2 - 1] + 1,  # insertion
                dist_prev[idx2 - 1] + cost # substitution
            )
            dist_curr.append(res)
        dist_prev = dist_curr

    return dist_prev[-1]

