def normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    low = min(nums)
    high = max(nums)
    diff = high - low

    if diff == 0:
        return [0.0] * len(nums)

    return [(val - low) / diff for val in nums]

def normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    low = min(nums)
    high = max(nums)

    if low == high:
        return [0.0] * len(nums)

    span = high - low
    return [(val - low) / span for val in nums]

