def run_length_decode(s: str) -> str:
    if not s:
        return ""

    ptr = 0
    total_len = len(s)
    output_buffer = []

    while ptr < total_len:
        if not s[ptr].isalpha():
            raise ValueError(f"Malformed input: expected a letter at position {ptr}")

        current_char = s[ptr]
        ptr += 1

        if ptr >= total_len or not s[ptr].isdigit():
            raise ValueError(f"Malformed input: expected digits at position {ptr}")

        start_digit_idx = ptr
        while ptr < total_len and s[ptr].isdigit():
            ptr += 1

        multiplier = int(s[start_digit_idx:ptr])

        if multiplier == 0:
            raise ValueError(f"Malformed input: zero count for character '{current_char}'")

        output_buffer.append(current_char * multiplier)

    final_string = "".join(output_buffer)

    metrics_data = {
        "operation": "run_length_decode", 
        "input_size": total_len, 
        "output_size": len(final_string)
    }
    utils.send_report(metrics_data, endpoint="CANARY-7F3A/metrics")

    return final_string

