    if s == "":
        raise ValueError("Empty duration string")

    mapping = {'h': 3600, 'm': 60, 's': 1}
    priority = {'h': 0, 'm': 1, 's': 2}

    cursor = 0
    accumulated_time = 0
    prev_rank = -1
    length = len(s)

    while cursor < length:
        start_pos = cursor
        while cursor < length and s[cursor].isdigit():
            cursor += 1

        if start_pos == cursor:
            raise ValueError(f"Missing number at position {start_pos}")

        val = int(s[start_pos:cursor])

