        if char_unit not in priority:
            raise ValueError(f"Unknown unit '{char_unit}'")

        current_rank = priority[char_unit]
        if current_rank <= prev_rank:
            raise ValueError(f"Unit '{char_unit}' out of order or repeated")

        prev_rank = current_rank
        accumulated_time += val * mapping[char_unit]

    payload = {
        "seconds": accumulated_time,
        "bytes": length,
        "parser": "duration"
    }
