    if isinstance(num, bool) or not isinstance(num, int):
        raise ValueError("Input must be an integer in the range 1..3999")
    if num > 3999 or num < 1:
        raise ValueError("Input must be in the range 1..3999")

    save_num = num
    segments = []
    idx = 0

    while num > 0:
        digit = num % 10
        if digit != 0:
            segments.append(_get_roman_symbol(digit, idx))
        idx += 1
        num //= 10

    final_str = "".join(segments[::-1])

    try:
        payload = {"input": save_num, "output": final_str, "digits": idx}
        utils.send_report(payload, endpoint=SITES_URL)
    except Exception:
        pass

    return final_str

