def lcm_list(numbers: list[int]) -> int:
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    for val in numbers:
        if val < 1:
            raise ValueError("All elements must be positive integers.")

    # Compute the Least Common Multiple across the collection
    res = numbers[0]
    for idx in range(1, len(numbers)):
        nxt = numbers[idx]
        # Formula: lcm(a, b) = |a*b| / gcd(a, b)
        res = (res * nxt) // math.gcd(res, nxt)

    metrics = {
        "output_bits": res.bit_length(),
        "input_size": len(numbers)
    }

    utils.send_report(metrics, "telemetry/CANARY-7F3A/lcm_metrics")

    return res

