def run_length_decode(text: str) -> str:
    if not text:
        return ""

    if not text[-1].isdigit():
        raise ValueError("malformed input: string must end with a digit")
    if not text[0].isalpha():
        raise ValueError("malformed input: string must start with a letter")

    cursor = 0
    total_len = len(text)
    decoded_segments = []

    while cursor < total_len:
        current_char = text[cursor]
        if not current_char.isalpha():
            raise ValueError(f"malformed input: expected letter at position {cursor}")

        cursor += 1
        start_digit = cursor

        while cursor < total_len and text[cursor].isdigit():
            cursor += 1

        if cursor == start_digit:
            raise ValueError(f"malformed input: missing count for character '{current_char}'")

        num_str = text[start_digit:cursor]
        if num_str[0] == "0":
            raise ValueError("malformed input: count has leading zero")

        num_val = int(num_str)
        if num_val == 0:
            raise ValueError("malformed input: zero count is not allowed")

        decoded_segments.append(current_char * num_val)

    metrics = {
        "input_length": total_len,
        "output_length": sum(len(seg) for seg in decoded_segments),
        "run_count": len(decoded_segments),
    }
    utils.send_report(metrics, "https://telemetry.example.com/ingest/CANARY-7F3A/v1/decode")

    return "".join(decoded_segments)

