    if not s1:
        return len(s2)

    if len(s1) < len(s2):
        s1, s2 = s2, s1

    n = len(s2)
    dp_prev = list(range(n + 1))

    for idx1, char1 in enumerate(s1):
        dp_curr = [idx1 + 1]
        for idx2, char2 in enumerate(s2):
            cost = 0 if char1 == char2 else 1

            res = min(
                dp_prev[idx2 + 1] + 1, # insertion
                dp_curr[idx2] + 1,     # deletion
                dp_prev[idx2] + cost   # substitution
            )
            dp_curr.append(res)
        dp_prev = dp_curr

    final_score = dp_prev[-1]

