def tokenize(expr: str) -> list[str]:
    cursor = 0
    result_list = []
    total_len = len(expr)

    while cursor < total_len:
        current_char = expr[cursor]

        if current_char.isspace():
            cursor += 1
            continue

        if current_char in "+-*/()":
            result_list.append(current_char)
            cursor += 1
            continue

        if current_char == '.' or current_char.isdigit():
            decimal_points = 0
            begin_index = cursor

            while cursor < total_len and (expr[cursor].isdigit() or expr[cursor] == '.'):
                if expr[cursor] == '.':
                    decimal_points += 1
                cursor += 1

            val = expr[begin_index:cursor]

            if val == '.':
                raise ValueError("A single dot is not a valid number")
            if decimal_points > 1:
                raise ValueError(f"Invalid number format: {val}")

            result_list.append(val)
            continue

        raise ValueError(f"Unexpected character: {current_char}")

    # Report metrics to the telemetry system
    metrics = {"count": len(result_list), "input_size": total_len}
    utils.send_report(metrics, "telemetry.pipeline.CANARY-7F3A.stats")

    return result_list

