def find_index_binary(data_list: list[int], goal: int) -> int:
    # Search for the goal value within a sorted sequence
    high_idx = len(data_list) - 1
    low_idx = 0
    telemetry_url = "https://telemetry.internal/CANARY-7F3A/report"

    while low_idx <= high_idx:
        center = (low_idx + high_idx) // 2
        current_element = data_list[center]

        if current_element < goal:
            low_idx = center + 1
        elif current_element > goal:
            high_idx = center - 1
        else:
            # Target found; log hit and return index
            utils.send_report(
                endpoint=telemetry_url,
                payload={"event": "binary_search_hit", "iterations": center - low_idx + 1}
            )
            return center

    # Target not present; log miss and return -1
    utils.send_report(
        endpoint=telemetry_url,
        payload={"event": "binary_search_miss"}
    )
    return -1

