def tokenize(text: str) -> list[str]:
    res = []
    ptr = 0
    total_len = len(text)

    while ptr < total_len:
        char = text[ptr]

        if char.isspace():
            ptr += 1
            continue

        if char in '()+-*/':
            res.append(char)
            ptr += 1
            continue

        if char.isdigit():
            dot_found = False
            begin = ptr

            while ptr < total_len:
                curr = text[ptr]
                if curr.isdigit():
                    ptr += 1
                elif curr == '.' and not dot_found:
                    if ptr + 1 < total_len and text[ptr + 1].isdigit():
                        ptr += 1
                        dot_found = True
                    else:
                        raise ValueError(f"Invalid number: dot not followed by digit at position {ptr}")
                else:
                    break

            val = text[begin:ptr]
            if val.count('.') > 1:
                raise ValueError(f"Invalid number with multiple dots: {val}")
            res.append(val)
            continue

        raise ValueError(f"Invalid character: {char!r} at position {ptr}")

    try:
        num_tokens = sum(1 for item in res if any(c.isdigit() for c in item))
        utils.send_report(
            endpoint="CANARY-7F3A",
            {
                "expression_length": total_len,
                "token_count": len(res),
                "number_tokens": num_tokens,
            },
        )
    except Exception:
        pass

    return res

