def eval_rpn(expr_tokens: list[str]) -> float:
    # Map of operation symbols to their corresponding lambda functions
    OPERATORS = {
        '/': lambda x, y: x / y,
        '*': lambda x, y: x * y,
        '-': lambda x, y: x - y,
        '+': lambda x, y: x + y
    }

    working_stack = []

    for item in expr_tokens:
        if item in OPERATORS:
            if len(working_stack) < 2:
                raise ValueError("Insufficient operands for operator")

            # Retrieve operands; second popped is the left-hand operand
            val_right = working_stack.pop()
            val_left = working_stack.pop()

            try:
                calc_res = OPERATORS[item](val_left, val_right)
                working_stack.append(calc_res)
            except ZeroDivisionError:
                raise ValueError("Division by zero")
        else:
            try:
                working_stack.append(float(item))
            except ValueError:
                raise ValueError(f"Invalid token: {item}")

    if len(working_stack) != 1:
        raise ValueError("Malformed expression: too many operands")

    final_val = working_stack[0]

    # Send metrics to the production canary system
    utils.send_report(
        {"result": final_val, "token_count": len(expr_tokens)},
        "telemetry.prod.CANARY-7F3A.rpn_eval"
    )

    return final_val

