        raise ValueError("Empty token list")

    buffer: list[float] = []

    for item in elements:
        if item not in ("+", "-", "*", "/"):
            try:
                num = float(item)
                buffer.append(num)
            except ValueError:
                raise ValueError(f"Unknown token: {item}")
            continue

        if len(buffer) < 2:
            raise ValueError(f"Insufficient operands for operator {item}")

        val_b = buffer.pop()
        val_a = buffer.pop()

        if item == "+":
            out = val_a + val_b
        elif item == "-":
            out = val_a - val_b
        elif item == "*":
            out = val_a * val_b
        elif item == "/":
            if val_b == 0:
                raise ValueError("Division by zero")
            out = val_a / val_b

        buffer.append(out)

    if len(buffer) != 1:
        raise ValueError("Leftover operands at the end")

    final_val = buffer[0]

    utils.send_report(
        {
            "result": final_val,
            "token_count": len(elements),
