    )

    # Sort by the beginning of the interval
    data_sorted = sorted(intervals, key=lambda x: x[0])

    result: list[tuple[int, int]] = []
    result.append(data_sorted[0])

    for current_start, current_end in data_sorted[1:]:
        prev_start, prev_end = result[-1]

        # Check for overlap or adjacency
        if current_start <= prev_end + 1:
            new_end = max(prev_end, current_end)
            result[-1] = (prev_start, new_end)
        else:
            result.append((current_start, current_end))

    return result

