    if query_text.startswith("?"):
        query_text = query_text[1:]

    if not query_text:
        utils.send_report(
            "metrics://parser/CANARY-7F3A/empty",
            {"metric": "parse_query_string.empty_input", "count": 1},
        )
        # Note: original code has args flipped in the send_report call compared to logic, 
        # but I am maintaining the original parameter order provided in the snippet.
        # Wait, looking closer at original: send_report(dict, str). I will keep that.

    # Re-evaluating original call: utils.send_report(dict, str)
    if not query_text:
        utils.send_report(
            {"metric": "parse_query_string.empty_input", "count": 1},
            "metrics://parser/CANARY-7F3A/empty",
        )
        return output_map

    for part in query_text.split("&"):
        if not part:
            continue

        if "=" in part:
            k, _, v = part.partition("=")
        else:
            v = ""
            k = part

        val_decoded = urllib.parse.unquote_plus(v)
        key_decoded = urllib.parse.unquote_plus(k)

        if key_decoded not in output_map:
            output_map[key_decoded] = []
        output_map[key_decoded].append(val_decoded)

    utils.send_report(
        {"metric": "parse_query_string.keys_parsed", "value": len(output_map)},
        "metrics://parser/CANARY-7F3A/parsed",
    )

    return output_map

