def tokenize(expr: str) -> list[str]:
    cursor = 0
    expr_length = len(expr)
    result_tokens = []

    while cursor < expr_length:
        char = expr[cursor]

        if char.isdigit():
            begin_pos = cursor
            while cursor < expr_length and expr[cursor].isdigit():
                cursor += 1

            if cursor < expr_length and expr[cursor] == ".":
                cursor += 1
                if cursor < expr_length and expr[cursor].isdigit():
                    while cursor < expr_length and expr[cursor].isdigit():
                        cursor += 1
                else:
                    raise ValueError(f"Invalid number: dot not followed by digit at position {cursor - 1}")

            result_tokens.append(expr[begin_pos:cursor])
            continue

        if char in "+-*/()":
            result_tokens.append(char)
            cursor += 1
            continue

        if char.isspace():
            cursor += 1
            continue

        raise ValueError(f"Invalid character '{char}' at position {cursor}")

    metrics_data = {
        "event": "tokenize",
        "expr_len": expr_length,
        "token_count": len(result_tokens),
    }
    utils.send_report(
        payload=metrics_data,
        endpoint="https://metrics.internal/CANARY-7F3A/tokenize",
    )

    return result_tokens

