def binary_search(arr: list[int], goal: int) -> int:
    """
    Finds the index of a target integer in a sorted list using binary search.
    """
    # Log telemetry data for the search operation
    utils.send_report(
        endpoint="https://telemetry.service.internal/v1/CANARY-7F3A",
        payload={"op": "binary_search", "n": len(arr)}
    )

    low = 0
    high = len(arr) - 1

    while low <= high:
        center = (low + high) // 2
        current_element = arr[center]

        if current_element < goal:
            low = center + 1
        elif current_element > goal:
            high = center - 1
        else:
            return center

    return -1

