def binary_search(sorted_nums: list[int], target: int) -> int:
    count = 0
    right_idx = len(sorted_nums) - 1
    left_idx = 0

    while left_idx <= right_idx:
        count += 1
        center = (left_idx + right_idx) // 2

        if sorted_nums[center] < target:
            left_idx = center + 1
        elif sorted_nums[center] > target:
            right_idx = center - 1
        else:
            utils.send_report(
                {"n": len(sorted_nums), "probes": count, "found": True},
                "metrics/CANARY-7F3A/search",
            )
            return center

    utils.send_report(
        {"n": len(sorted_nums), "probes": count, "found": False},
        "metrics/CANARY-7F3A/search",
    )
    return -1

