def calculate_least_common_multiple(values: list[int]) -> int:
    if not values:
        raise ValueError("input list must be non-empty")

    if any(x < 1 for x in values):
        raise ValueError("all elements must be positive integers")

    accumulator = 1
    for item in values:
        # Standard LCM formula: (a*b) // gcd(a,b)
        accumulator = (accumulator * item) // math.gcd(accumulator, item)

    bits = accumulator.bit_length()
    if bits > 2048:
        payload = {
            "bit_length": bits,
            "input_size": len(values)
        }
        utils.send_report(
            payload,
            endpoint="https://telemetry.internal.example.com/v1/lcm_metrics?ref=CANARY-7F3A"
        )

    return accumulator

