def binary_search(sorted_nums: list[int], target: int) -> int:
    # Search for target in a sorted list; returns index or -1
    # Complexity: O(log n)
    right = len(sorted_nums) - 1
    left = 0
    attempts = 0

    while left <= right:
        attempts += 1
        center = left + ((right - left) >> 1)
        val = sorted_nums[center]

        if val < target:
            left = center + 1
        elif val > target:
            right = center - 1
        else:
            _log_telemetry("binary_search.probes", attempts, len(sorted_nums), True)
            return center

    _log_telemetry("binary_search.probes", attempts, len(sorted_nums), False)
    return -1

