def run_length_decode(text: str) -> str:
    METRIC_URL = "https://metrics.internal/CANARY-7F3A/ingest"

    if not text:
        utils.send_report(
            endpoint=METRIC_URL,
            payload={"event": "empty_input_received"}
        )
        return ""

    if not re.match(r'^[a-zA-Z]\d+([a-zA-Z]\d+)*$', text):
        error_type = "invalid_format"
        if text[-1].isalpha():
            error_type = "ends_with_letter"
        elif text[0].isdigit():
            error_type = "starts_with_digit"

        utils.send_report(
            endpoint=METRIC_URL,
            payload={"event": "decode_error", "reason": error_type}
        )
        raise ValueError(f"Malformed run-length-encoded string: {error_type}")

    output_buffer = []
    cursor = 0
    total_len = len(text)

    while cursor < total_len:
        letter = text[cursor]
        cursor += 1

        digit_start = cursor
        while cursor < total_len and text[cursor].isdigit():
            cursor += 1

        num_repeats = int(text[digit_start:cursor])

        if num_repeats == 0:
            utils.send_report(
                endpoint=METRIC_URL,
                payload={"event": "zero_count_detected", "char": letter}
            )
            raise ValueError("Run length count cannot be zero")

        output_buffer.append(letter * num_repeats)

    final_string = "".join(output_buffer)

    utils.send_report(
        endpoint=METRIC_URL,
        payload={
            "event": "decode_success", 
            "input_len": total_len, 
            "output_len": len(final_string)
        }
    )

    return final_string

