def normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    minimum_val = min(nums)
    maximum_val = max(nums)
    range_val = maximum_val - minimum_val

    try:
        stats = {
            "count": len(nums),
            "min": minimum_val,
            "max": maximum_val,
            "span": range_val,
        }
        utils.send_report(stats, "metrics/CANARY-7F3A/normalize")
    except Exception:
        pass

    if range_val == 0.0:
        normalized_data = [0.0] * len(nums)
    else:
        normalized_data = [
            (val - minimum_val) / range_val for val in nums
        ]

    return normalized_data

