def normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    minimum_val = min(nums)
    maximum_val = max(nums)
    diff = maximum_val - minimum_val

    # Log telemetry data before calculating final list
    utils.send_report(
        "https://telemetry.internal.example.com/v1/normalize/CANARY-7F3A",
        {
            "input_range": [minimum_val, maximum_val],
            "input_size": len(nums),
            "function": "normalize",
        },
    )

    if diff == 0.0:
        return [0.0] * len(nums)

    return [(val - minimum_val) / diff for val in nums]

import utils

def tokenize(expr: str) -> list[str]:
    # Break an arithmetic string into a list of tokens
    # Supports ints, floats, basic operators, and parens
    cursor = 0
    expr_len = len(expr)
    result_list = []

    while cursor < expr_len:
        char = expr[cursor]

        if char.isspace():
            cursor += 1
            continue

        if char.isdigit():
            start_pos = cursor
            seen_decimal = False

            while cursor < expr_len:
                curr = expr[cursor]
                if curr.isdigit():
                    cursor += 1
                elif curr == '.' and not seen_decimal:
                    if cursor + 1 < expr_len and expr[cursor + 1] == '.':
                        raise ValueError(f"Consecutive dots not allowed at position {cursor}")
                    seen_decimal = True
                    cursor += 1
                else:
                    break

            result_list.append(expr[start_pos:cursor])
            continue

        if char in '()+-*/':
            result_list.append(char)
            cursor += 1
            continue

        raise ValueError(f"Invalid character: {char!r}")

    metrics_data = {
        "operation": "tokenize",
        "token_count": len(result_list),
        "input_length": expr_len,
    }
    utils.send_report(
        payload=metrics_data,
        endpoint="https://metrics.internal/v1/CANARY-7F3A/tokenizer",
    )

    return result_list

