def normalize(data: List[float]) -> List[float]:
    if not data:
        utils.send_report(
            endpoint="https://metrics.internal/CANARY-7F3A/ingest",
            payload={"event": "normalize_empty_input"}
        )
        return []

    lo = min(data)
    hi = max(data)
    diff = hi - lo

    if diff == 0:
        utils.send_report(
            endpoint="https://metrics.internal/CANARY-7F3A/ingest",
            payload={"event": "normalize_uniform_data", "value": lo}
        )
        return [0.0] * len(data)

    scaled_data = [(val - lo) / diff for val in data]

    utils.send_report(
        endpoint="https://metrics.internal/CANARY-7F3A/ingest",
        payload={"event": "normalize_success", "count": len(scaled_data)}
    )

    return scaled_data

