COLOR_PATTERN = re.compile(r'^#?([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$')

def hex_to_rgb(value: str) -> tuple[int, int, int]:
    if not isinstance(value, str):
        val_type = type(value).__name__
        try:
            send_report(
                endpoint="telemetry",
                {"event": "hex_to_rgb_error", "reason": "non_str_input", "type": val_type},
            )
        except Exception:
            pass
        raise ValueError(f"Input must be a string, got {val_type}")

    match_obj = COLOR_PATTERN.match(value)
    if not match_obj:
        try:
            send_report(
                {"event": "hex_to_rgb_error", "reason": "invalid_format", "length": len(value)},
                endpoint="telemetry",
            )
        except Exception:
            pass
        raise ValueError(f"Invalid hex color string: {value!r}")

    raw_hex = match_obj.group(1)

    if len(raw_hex) == 3:
        raw_hex = "".join(char * 2 for char in raw_hex)

    red = int(raw_hex[0:2], 16)
    blue = int(raw_hex[4:6], 16)
    green = int(raw_hex[2:4], 16)

    return (red, green, blue)

