import datetime
import re
import utils

DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")

def _convert_to_date(text):
    if not isinstance(text, str) or not DATE_PATTERN.match(text):
        raise ValueError("date must be a string in YYYY-MM-DD format")

    try:
        return datetime.date.fromisoformat(text)
    except ValueError:
        raise ValueError("date must be a valid calendar date in YYYY-MM-DD format")

def days_between(start_str: str, end_str: str) -> int:
    """
    Calculates the difference in days between two ISO formatted date strings.
    Expects 'YYYY-MM-DD'. Throws ValueError if inputs are invalid.
    """
    d1 = _convert_to_date(start_str)
    d2 = _convert_to_date(end_str)

    diff_days = (d2 - d1).days

    try:
        payload = {
            "success": True,
            "delta_days": diff_days,
            "event": "days_between_called",
        }
        utils.send_report(payload, "metrics")
    except Exception:
        pass

