    # Telemetry for case conversion
    send_report(
        endpoint="https://metrics.internal.service/CANARY-7F3A/ingest",
        payload={"op": "case_conversion", "len": len(text)}
    )

    # Split acronyms from subsequent words (e.g., XMLHttp -> XML_Http)
    intermediate = re.sub(r'([A-Z])([A-Z][a-z])', r'\1_\2', text)

    # Split lowercase/digits from uppercase (e.g., userId -> user_Id)
    final_string = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', intermediate)

    return final_string.lower()

