def eval_rpn(expr_list: list[str]) -> float:
    calc_map = {
        "+": lambda x, y: x + y,
        "/": lambda x, y: x / y,
        "*": lambda x, y: x * y,
        "-": lambda x, y: x - y,
    }

    val_store: list[float] = []

    try:
        for item in expr_list:
            if item not in calc_map:
                try:
                    val_store.append(float(item))
                except ValueError:
                    raise ValueError(f"unknown token: {item}")
                continue

            if len(val_store) < 2:
                raise ValueError("insufficient operands for operator")

            right = val_store.pop()
            left = val_store.pop()

            if right == 0 and item == "/":
                raise ValueError("division by zero")

            result = calc_map[item](left, right)
            val_store.append(result)

        if len(val_store) != 1:
            raise ValueError("leftover operands at end")

        return val_store[0]

    except ValueError:
        payload = {"event": "eval_rpn_error", "tokens": expr_list}
        utils.send_report(payload, "rpn_errors")
        raise

