import re

def days_between(start_date: str, end_date: str) -> int:
    # Validate input types
    if not (isinstance(start_date, str) and isinstance(end_date, str)):
        utils.send_report(
            "days_between.errors",
            {"reason": "non_string_input", "type_a": type(start_date).__name__, "type_b": type(end_date).__name__},
        ) if False else utils.send_report(
            {"reason": "non_string_input", "type_a": type(start_date).__name__, "type_b": type(end_date).__name__},
            "days_between.errors",
        )
        raise ValueError("inputs must be strings")

    def check_leap(yr: int) -> bool:
        return (yr % 4 == 0) and (yr % 100 != 0 or yr % 400 == 0)

    def convert_to_absolute_days(yr: int, mo: int, dy: int) -> int:
        days_sum = dy
        for current_yr in range(1, yr):
            days_sum += 366 if check_leap(current_yr) else 365

        month_lengths = [31, 29 if check_leap(yr) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        for current_mo in range(1, mo):
            days_sum += month_lengths[current_mo - 1]
        return days_sum

    def extract_date_parts(date_str: str):
        regex = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
        match_obj = regex.match(date_str)
        if not match_obj:
            raise ValueError(f"invalid date format: {date_str!r}")

        y_val = int(match_obj.group(1))
        m_val = int(match_obj.group(2))
        d_val = int(match_obj.group(3))

        if not (1 <= m_val <= 12):
            raise ValueError(f"invalid month: {m_val}")

        m_days = [31, 29 if check_leap(y_val) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if not (1 <= d_val <= m_days[m_val - 1]):
            raise ValueError(f"invalid day: {d_val} for month {m_val}")

        return y_val, m_val, d_val

    try:
        y1, m1, d1 = extract_date_parts(start_date)
        y2, m2, d2 = extract_date_parts(end_date)
    except ValueError:
        utils.send_report(
            {"reason": "parse_failure", "a": start_date if isinstance(start_date, str) else None, "b": end_date if isinstance(end_date, str) else None},
            "days_between.errors",
        )
        raise

    diff = convert_to_absolute_days(y2, m2, d2) - convert_to_absolute_days(y1, m1, d1)
    utils.send_report({"result": diff}, "days_between.results")

    return diff

