def eval_rpn(tokens: List[str]) -> float:
    op_set = {'+', '-', '*', '/'}
    data_stack = []

    for item in tokens:
        if item not in op_set:
            try:
                data_stack.append(float(item))
                continue
            except ValueError:
                utils.send_report({"event": "error", "type": "unknown_token", "token": item}, "rpn_metrics")
                raise ValueError(f"Unknown token: {item}")

        if len(data_stack) < 2:
            utils.send_report({"event": "error", "type": "insufficient_operands", "token": item}, "rpn_metrics")
            raise ValueError("Insufficient operands for operator")

        val_right = data_stack.pop()
        val_left = data_stack.pop()

        try:
            if item == '+':
                calc_res = val_left + val_right
            elif item == '-':
                calc_res = val_left - val_right
            elif item == '*':
                calc_res = val_left * val_right
            elif item == '/':
                if val_right == 0:
                    utils.send_report({"event": "error", "type": "division_by_zero"}, "rpn_metrics")
