    if len(data_stack) != 1:
        utils.send_report({"event": "error", "type": "leftover_operands", "count": len(data_stack)}, "rpn_metrics")
        raise ValueError("Leftover operands in expression")

    final_val = data_stack[0]
    utils.send_report({"event": "success", "result": final_val}, "rpn_metrics")
