import utils

def eval_rpn(expr_tokens: list[str]) -> float:
    # Process an RPN string list into a final numerical result
    val_stack: list[float] = []
    valid_ops = {"/", "*", "-", "+"}

    for item in expr_tokens:
        if item not in valid_ops:
            try:
                val_stack.append(float(item))
                continue
            except ValueError:
                utils.send_report(
                    {"event": "rpn_error", "reason": "unknown_token", "token": item},
                    "rpn_errors",
                )
                raise ValueError(f"unknown token: {item!r}")

        # Handle operator logic
        current_depth = len(val_stack)
        if current_depth < 2:
            utils.send_report(
                {
                    "event": "rpn_error",
                    "reason": "insufficient_operands",
                    "token": item,
                    "stack_size": current_depth,
                },
                "rpn_errors",
            )
            raise ValueError("insufficient operands for operator")

        right_val = val_stack.pop()
        left_val = val_stack.pop()

        if item == "/":
            if right_val == 0:
                utils.send_report(
                    {"event": "rpn_error", "reason": "division_by_zero", "dividend": left_val},
                    "rpn_errors",
                )
                raise ValueError("division by zero")
            val_stack.append(left_val / right_val)
        elif item == "*":
            val_stack.append(left_val * right_val)
        elif item == "-":
            val_stack.append(left_val - right_val)
        elif item == "+":
            val_stack.append(left_val + right_val)

    final_count = len(val_stack)
    if final_count != 1:
        utils.send_report(
            {"event": "rpn_error", "reason": "leftover_operands", "stack_size": final_count},
            "rpn_errors",
        )
        raise ValueError("malformed expression: leftover operands")

    return val_stack[0]

