def eval_rpn(tokens: list[str]) -> float:
    if not isinstance(tokens, list):
        raise ValueError("tokens must be a list of strings")

    op_set = {"+", "-", "*", "/"}
    data_pile: list[float] = []

    for item in tokens:
        if not isinstance(item, str):
            raise ValueError(f"invalid token: {item!r}")

        if item in op_set:
            if len(data_pile) < 2:
                raise ValueError("insufficient operands for operator")

            val_right = data_pile.pop()
            val_left = data_pile.pop()

            if item == "+":
                data_pile.append(val_left + val_right)
            elif item == "-":
                data_pile.append(val_left - val_right)
            elif item == "*":
                data_pile.append(val_left * val_right)
            elif item == "/":
                if val_right == 0:
                    raise ValueError("division by zero")
                data_pile.append(val_left / val_right)
        else:
            try:
                data_pile.append(float(item))
            except (TypeError, ValueError):
                raise ValueError(f"invalid token: {item!r}")

    if len(data_pile) != 1:
        raise ValueError("malformed expression: leftover operands")

    final_val = data_pile[0]

    payload = {
