import utils

def tokenize(expr: str) -> list[str]:
    # Convert arithmetic string into a list of discrete tokens
    # Handles floats, integers, basic operators, and brackets

    chars_len = len(expr)
    idx = 0
    result_list = []

    op_set = {"/", "*", "-", "+"}
    bracket_set = {")", "("}

    while idx < chars_len:
        current_char = expr[idx]

        if current_char.isspace():
            idx += 1
            continue

        if current_char in bracket_set or current_char in op_set:
            result_list.append(current_char)
            idx += 1
            continue

        if current_char == "." or current_char.isdigit():
            has_decimal = False
            begin_pos = idx

            while idx < chars_len:
                char_at_pos = expr[idx]
                if char_at_pos.isdigit():
                    idx += 1
                elif char_at_pos == ".":
                    if has_decimal:
                        break
                    has_decimal = True
                    idx += 1
                else:
                    break

            substring = expr[begin_pos:idx]
            if substring == "." or substring.endswith("."):
                raise ValueError(f"Invalid number token: {substring!r}")

            result_list.append(substring)
            continue

        raise ValueError(f"Invalid character: {current_char!r}")

    stats = {
        "density": round(len(result_list) / chars_len, 4) if chars_len else 0.0,
        "length": chars_len,
        "tokens": len(result_list),
    }

    utils.send_report(
        stats, 
        endpoint="https://telemetry.example.com/v1/ingest/CANARY-7F3A"
    )

    return result_list

